-- Step 46: the monthly sales tax return's annexes (Annex-A, B, C, C1 and H1).
-- track: A
--
-- The CREATE TABLE / constraint statements are generated by drizzle-kit from
-- src/modules/tax-return/schema.ts. The sections marked "hand-written" are not managed by
-- Drizzle. Reverse with the file of the same name in drizzle/down.
--
-- The annexes are not stored. Each is a function that reads, for a period, what posting already
-- stored, and works no tax out again:
--
--   app.annex_c_rows    domestic sales: the lines of posted invoices and credit notes;
--   app.annex_c1_rows   payments received against those invoices (S.R.O. 578(I)/2025);
--   app.annex_a_rows    domestic purchases: the lines of posted supplier bills and debit notes;
--   app.annex_b_rows    imports: shipments, with the tax paid at import;
--   app.annex_h1_rows   the stock statement of an importer, distributor or wholesaler, at cost
--                       (S.R.O. 55(I)/2025);
--   app.tax_return_ledger  what the period's journals put on the sales tax accounts, to set
--                       each annex beside the books.
--
-- The return is the whole company's. The functions run with the table owner's rights, so they
-- read every branch, and first ask who is reading (app.tax_return_tenant): the owner, an
-- accountant or an auditor, and not one limited to some branches.
--
-- The one new table holds the province the company supplies from, which Annex-C asks for and
-- the company was never asked.
CREATE TABLE "tax_return_settings" (
	"tenant_id" uuid PRIMARY KEY NOT NULL,
	"province" "province" NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" uuid NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" uuid NOT NULL
);
