-- ── hand-written: who reads the return ──────────────────────────────────────────────────────────
-- The company the return is read for, after asking who is reading. The return is the whole
-- company's, so it is read only by the owner, an accountant or an auditor who is not limited to
-- some branches: half a return is worse than none. Every function below begins here, and runs
-- with the table owner's rights so that it reads every branch once this has said yes.
CREATE FUNCTION app.tax_return_tenant() RETURNS uuid
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
BEGIN
  IF v_tenant IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'auditor') THEN
    RAISE EXCEPTION 'only the owner, an accountant or an auditor reads the sales tax return' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'the sales tax return covers the whole company; a member limited to some branches does not read it' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN v_tenant;
END $$;
