REVOKE ALL ON FUNCTION app.tax_return_tenant() FROM PUBLIC;
--> statement-breakpoint

-- ── hand-written: Annex-C, domestic sales ───────────────────────────────────────────────────────
-- One row for each line of each posted sales invoice and credit note dated in the period, as
-- posting stored it: the buyer as written on the document, and the line's value, tax, further
-- tax and extra tax. No tax is worked out again. The one figure made here is the retail value of
-- a Third Schedule line, the retail price of one base unit times the base units on the line: a
-- credit note's line keeps a copy of its invoice's whole retail value, not its own share.
-- Amounts are positive for both kinds; a credit note names the invoice it corrects. The sales tax of the invoices less that of the credit notes
-- is what the period's journals put on the output tax account (app.tax_return_ledger).
CREATE FUNCTION app.annex_c_rows(p_from date, p_to date)
  RETURNS TABLE (
    doc_kind text, document_number text, document_date date,
    buyer_name text, buyer_ntn text, buyer_cnic text, buyer_strn text, buyer_registration_type text, buyer_province text,
    original_number text, original_date date,
    line_no integer, hs_code text, description text, sale_type text, tax_kind text, tax_rate numeric,
    quantity numeric, uom text, value numeric, retail_value numeric,
    sales_tax numeric, extra_tax numeric, further_tax numeric,
    sro_schedule_no text, sro_item_serial text, total numeric
  )
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tax_return_tenant();
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RAISE EXCEPTION 'a period is needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  RETURN QUERY
    SELECT d.kind, d.number, d.document_date,
      d.buyer_name, d.buyer_ntn, d.buyer_cnic, d.buyer_strn, d.buyer_registration_type, d.buyer_province,
      o.number, o.document_date,
      l.line_no, l.hs_code, l.description, l.sale_type, l.tax_kind, l.tax_rate,
      l.base_quantity, coalesce(l.fbr_uom_code, u.name), l.value,
      CASE WHEN l.tax_kind = 'third_schedule' AND l.retail_price IS NOT NULL THEN round(l.retail_price * l.base_quantity, 2) END,
      l.tax_amount, l.extra_tax_amount, l.further_tax_amount,
      l.sro_schedule_no, l.sro_item_serial, l.total
    FROM public.sales_documents d
    JOIN public.sales_lines l ON l.tenant_id = d.tenant_id AND l.document_id = d.id
    LEFT JOIN public.sales_documents o ON o.tenant_id = d.tenant_id AND o.id = d.source_document_id AND d.kind = 'credit_note'
    LEFT JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
    LEFT JOIN public.units u ON u.tenant_id = i.tenant_id AND u.id = i.base_unit_id
    WHERE d.tenant_id = v_tenant AND d.kind IN ('invoice', 'credit_note') AND d.status = 'submitted'
      AND d.posted_txid IS NOT NULL AND d.document_date BETWEEN p_from AND p_to
    ORDER BY d.document_date, d.number, l.line_no;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.annex_c_rows(date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.annex_c_rows(date, date) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: Annex-C1, payments received against domestic sales invoices ───────────────────
-- One row for each part of a posted receipt set against an invoice in the period (and not taken
-- back since): the buyer as written on the invoice, the invoice, and how the money came. The
-- period is the day the money was set against the invoice, which for an advance is later than
-- the day it was received; both days are given.
CREATE FUNCTION app.annex_c1_rows(p_from date, p_to date)
  RETURNS TABLE (
    receipt_number text, receipt_date date, method text, cheque_number text, cheque_bank text, reference text,
    buyer_name text, buyer_ntn text, buyer_cnic text, buyer_strn text, buyer_registration_type text,
    invoice_number text, invoice_date date, invoice_total numeric, invoice_tax numeric,
    amount numeric, allocated_on date
  )
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tax_return_tenant();
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RAISE EXCEPTION 'a period is needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  RETURN QUERY
    SELECT r.number, r.receipt_date, r.method, r.cheque_number, r.cheque_bank, r.reference,
      d.buyer_name, d.buyer_ntn, d.buyer_cnic, d.buyer_strn, d.buyer_registration_type,
      d.number, d.document_date, d.total, d.tax_total + d.further_tax_total + d.extra_tax_total,
      a.amount, a.allocated_on
    FROM public.receipt_allocations a
    JOIN public.receipts r ON r.tenant_id = a.tenant_id AND r.id = a.receipt_id
    JOIN public.sales_documents d ON d.tenant_id = a.tenant_id AND d.id = a.invoice_id
    WHERE a.tenant_id = v_tenant AND a.invoice_id IS NOT NULL AND a.voided_at IS NULL AND a.posted_at IS NOT NULL
      AND r.status = 'posted' AND a.allocated_on BETWEEN p_from AND p_to
    ORDER BY a.allocated_on, r.number, d.number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.annex_c1_rows(date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.annex_c1_rows(date, date) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: Annex-A, domestic purchases ───────────────────────────────────────────────────
-- One row for each line of each posted supplier bill dated in the period, and for each billed
-- line of each posted supplier return (a debit note), as posting stored them. What a bill pays
-- to customs for a shipment (sales tax at import, income tax at import, a deposit) is not a
-- purchase and is left to Annex-B, unless the line itself carries sales tax, which is input tax
-- of this annex whatever the line was put on a shipment as. The supplier is as it stands today:
-- a bill keeps no copy of the supplier's numbers. Sales tax withheld from the supplier is shown
-- once, on the first of the bill's lines listed here; a bill with none of its lines here and
-- tax withheld gets a row for the withholding alone.
CREATE FUNCTION app.annex_a_rows(p_from date, p_to date)
  RETURNS TABLE (
    doc_kind text, document_number text, supplier_invoice_no text, document_date date,
    supplier_name text, supplier_ntn text, supplier_cnic text, supplier_strn text, supplier_registration_type text, supplier_province text,
    original_number text, original_date date,
    line_no integer, line_kind text, hs_code text, description text, tax_rate numeric,
    quantity numeric, uom text, value numeric, sales_tax numeric, st_withheld numeric, total numeric
  )
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tax_return_tenant();
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RAISE EXCEPTION 'a period is needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  RETURN QUERY
    SELECT x.doc_kind, x.document_number, x.supplier_invoice_no, x.document_date,
      s.name, s.ntn, s.cnic, s.strn, s.registration_type::text, s.province::text,
      x.original_number, x.original_date,
      x.line_no, x.line_kind, i.hs_code, x.description, x.tax_rate,
      x.quantity, coalesce(i.fbr_uom_code, u.name), x.value, x.sales_tax, x.st_withheld, x.value + x.sales_tax
    FROM (
      SELECT 'bill'::text AS doc_kind, k.number AS document_number, k.supplier_invoice_no, k.bill_date AS document_date,
        k.supplier_id, NULL::text AS original_number, NULL::date AS original_date,
        k.line_no, k.line_kind, k.item_id, k.description, k.tax_rate, k.quantity, k.value, k.sales_tax,
        CASE WHEN k.line_no = min(k.line_no) OVER (PARTITION BY k.bill_id) THEN k.withheld ELSE 0 END AS st_withheld
      FROM (
        SELECT b.id AS bill_id, b.number, b.supplier_invoice_no, b.bill_date, b.supplier_id, w.withheld,
          l.line_no, l.kind AS line_kind, l.item_id, l.description, l.tax_rate,
          CASE WHEN g.id IS NOT NULL THEN l.quantity * g.unit_factor ELSE l.quantity END AS quantity,
          l.amount AS value, l.sales_tax
        FROM public.supplier_bills b
        CROSS JOIN LATERAL (
          SELECT coalesce(sum(e.amount), 0) AS withheld FROM public.withholding_entries e
          WHERE e.tenant_id = b.tenant_id AND e.bill_id = b.id AND e.kind = 'sales_tax') w
        JOIN public.supplier_bill_lines l ON l.tenant_id = b.tenant_id AND l.bill_id = b.id
        LEFT JOIN public.goods_receipt_lines g ON g.tenant_id = l.tenant_id AND g.id = l.receipt_line_id
        WHERE b.tenant_id = v_tenant AND b.status = 'posted' AND b.bill_date BETWEEN p_from AND p_to
          AND (l.sales_tax <> 0 OR NOT EXISTS (
            SELECT 1 FROM public.shipment_charges c
            WHERE c.tenant_id = l.tenant_id AND c.bill_line_id = l.id AND c.class IN ('sales_tax', 'advance_income_tax', 'deposit')))
      ) k
      UNION ALL
      -- A bill all of whose lines went to Annex-B, with sales tax withheld from its supplier.
      SELECT 'bill'::text, b.number, b.supplier_invoice_no, b.bill_date,
        b.supplier_id, NULL::text, NULL::date,
        0, 'expense'::text, NULL::uuid, 'Sales tax withheld; the bill''s lines are on Annex-B'::text, NULL::numeric, NULL::numeric, 0::numeric, 0::numeric,
        w.withheld
      FROM public.supplier_bills b
      CROSS JOIN LATERAL (
        SELECT coalesce(sum(e.amount), 0) AS withheld FROM public.withholding_entries e
        WHERE e.tenant_id = b.tenant_id AND e.bill_id = b.id AND e.kind = 'sales_tax') w
      WHERE b.tenant_id = v_tenant AND b.status = 'posted' AND b.bill_date BETWEEN p_from AND p_to AND w.withheld <> 0
        AND NOT EXISTS (
          SELECT 1 FROM public.supplier_bill_lines l
          WHERE l.tenant_id = b.tenant_id AND l.bill_id = b.id
            AND (l.sales_tax <> 0 OR NOT EXISTS (
              SELECT 1 FROM public.shipment_charges c
              WHERE c.tenant_id = l.tenant_id AND c.bill_line_id = l.id AND c.class IN ('sales_tax', 'advance_income_tax', 'deposit'))))
      UNION ALL
      SELECT 'debit_note'::text, r.number, r.supplier_reference, r.return_date,
        r.supplier_id, ob.number, ob.bill_date,
        rl.line_no, 'goods'::text, rl.item_id, bl.description, bl.tax_rate,
        rl.base_quantity, rl.amount, rl.sales_tax, 0::numeric
      FROM public.supplier_returns r
      JOIN public.supplier_return_lines rl ON rl.tenant_id = r.tenant_id AND rl.return_id = r.id
      JOIN public.supplier_bill_lines bl ON bl.tenant_id = rl.tenant_id AND bl.id = rl.bill_line_id
      JOIN public.supplier_bills ob ON ob.tenant_id = bl.tenant_id AND ob.id = bl.bill_id
      WHERE r.tenant_id = v_tenant AND r.status = 'posted' AND r.return_date BETWEEN p_from AND p_to
    ) x
    JOIN public.suppliers s ON s.tenant_id = v_tenant AND s.id = x.supplier_id
    LEFT JOIN public.items i ON i.tenant_id = v_tenant AND i.id = x.item_id
    LEFT JOIN public.units u ON u.tenant_id = i.tenant_id AND u.id = i.base_unit_id
    ORDER BY x.document_date, x.document_number, x.line_no;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.annex_a_rows(date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.annex_a_rows(date, date) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: Annex-B, imports ──────────────────────────────────────────────────────────────
-- One row for each spreading of a shipment's charges in the period that is its first (the first
-- made, whatever day it was dated), or that carries tax paid at import: the goods declaration, and the sales tax and income tax paid at
-- import that the spreading took into the books. The period is the day of the spreading, which
-- is when the input tax reached the ledger; the goods declaration's own date is given beside it.
CREATE FUNCTION app.annex_b_rows(p_from date, p_to date)
  RETURNS TABLE (
    shipment_number text, gd_number text, gd_date date, port text, origin text, supplier_name text,
    hs_codes text, customs_value numeric, sales_tax numeric, income_tax numeric, allocated_on date, first_spreading boolean
  )
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tax_return_tenant();
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RAISE EXCEPTION 'a period is needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  RETURN QUERY
    SELECT h.number, h.gd_number, h.gd_date, h.port, h.origin, s.name,
      (SELECT string_agg(DISTINCT i.hs_code, ', ' ORDER BY i.hs_code)
         FROM public.shipment_receipts sr
         JOIN public.goods_receipt_lines g ON g.tenant_id = sr.tenant_id AND g.receipt_id = sr.receipt_id
         JOIN public.items i ON i.tenant_id = g.tenant_id AND i.id = g.item_id
         WHERE sr.tenant_id = h.tenant_id AND sr.shipment_id = h.id AND i.hs_code IS NOT NULL),
      h.customs_value, t.sales_tax, t.income_tax, a.allocated_on, f.first_id = a.id
    FROM public.shipment_allocations a
    JOIN public.shipments h ON h.tenant_id = a.tenant_id AND h.id = a.shipment_id
    JOIN public.suppliers s ON s.tenant_id = h.tenant_id AND s.id = h.supplier_id
    CROSS JOIN LATERAL (
      SELECT coalesce(sum(c.amount) FILTER (WHERE c.class = 'sales_tax'), 0) AS sales_tax,
             coalesce(sum(c.amount) FILTER (WHERE c.class = 'advance_income_tax'), 0) AS income_tax
      FROM public.shipment_charges c WHERE c.tenant_id = a.tenant_id AND c.allocation_id = a.id) t
    CROSS JOIN LATERAL (
      SELECT e.id AS first_id FROM public.shipment_allocations e
      WHERE e.tenant_id = a.tenant_id AND e.shipment_id = a.shipment_id
      ORDER BY e.created_at, e.id LIMIT 1) f
    WHERE a.tenant_id = v_tenant AND a.allocated_on BETWEEN p_from AND p_to
      AND (f.first_id = a.id OR t.sales_tax <> 0 OR t.income_tax <> 0)
    ORDER BY a.allocated_on, h.number, a.created_at;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.annex_b_rows(date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.annex_b_rows(date, date) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: Annex-H1, the stock statement ─────────────────────────────────────────────────
-- One row for each item that had stock or moved in the period, at what the stock is carried at
-- (cost), from the stock moves posting wrote: what was held when the period opened, what came in
-- from abroad (goods received on a shipment, and the charges spread onto them), what was bought
-- at home (less what went back to suppliers), what was supplied (less what customers sent back),
-- everything else (counts and adjustments; a transfer between warehouses nets to nothing), and
-- what was held when it closed. The rate is the rate on the last day of the item's tax category,
-- or of the company's standard-rate category for an item with none of its own, which is what a
-- sale of it is charged.
CREATE FUNCTION app.annex_h1_rows(p_from date, p_to date)
  RETURNS TABLE (
    item_code text, item_name text, hs_code text, uom text, tax_rate numeric,
    opening_quantity numeric, opening_value numeric,
    imported_quantity numeric, imported_value numeric,
    purchased_quantity numeric, purchased_value numeric,
    supplied_quantity numeric, supplied_value numeric,
    other_quantity numeric, other_value numeric,
    closing_quantity numeric, closing_value numeric
  )
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tax_return_tenant();
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RAISE EXCEPTION 'a period is needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  RETURN QUERY
    WITH moves AS (
      SELECT m.item_id, m.quantity, m.value, m.move_date < p_from AS before,
        CASE
          WHEN m.source_type = 'landed_cost' THEN 'imported'
          WHEN m.source_type = 'goods_receipt' AND EXISTS (
            SELECT 1 FROM public.shipment_receipts sr WHERE sr.tenant_id = m.tenant_id AND sr.receipt_id = m.source_id) THEN 'imported'
          WHEN m.source_type = 'supplier_return' AND EXISTS (
            SELECT 1 FROM public.supplier_returns r
            JOIN public.shipment_receipts sr ON sr.tenant_id = r.tenant_id AND sr.receipt_id = r.receipt_id
            WHERE r.tenant_id = m.tenant_id AND r.id = m.source_id) THEN 'imported'
          WHEN m.source_type IN ('goods_receipt', 'supplier_return') THEN 'purchased'
          WHEN m.source_type IN ('sales_invoice', 'delivery_note', 'credit_note') THEN 'supplied'
          ELSE 'other'
        END AS class
      FROM public.stock_moves m
      WHERE m.tenant_id = v_tenant AND m.move_date <= p_to
    ), sums AS (
      SELECT v.item_id,
        coalesce(sum(v.quantity) FILTER (WHERE v.before), 0) AS oq, coalesce(sum(v.value) FILTER (WHERE v.before), 0) AS ov,
        coalesce(sum(v.quantity) FILTER (WHERE NOT v.before AND v.class = 'imported'), 0) AS iq, coalesce(sum(v.value) FILTER (WHERE NOT v.before AND v.class = 'imported'), 0) AS iv,
        coalesce(sum(v.quantity) FILTER (WHERE NOT v.before AND v.class = 'purchased'), 0) AS pq, coalesce(sum(v.value) FILTER (WHERE NOT v.before AND v.class = 'purchased'), 0) AS pv,
        coalesce(sum(v.quantity) FILTER (WHERE NOT v.before AND v.class = 'supplied'), 0) AS sq, coalesce(sum(v.value) FILTER (WHERE NOT v.before AND v.class = 'supplied'), 0) AS sv,
        coalesce(sum(v.quantity) FILTER (WHERE NOT v.before AND v.class = 'other'), 0) AS xq, coalesce(sum(v.value) FILTER (WHERE NOT v.before AND v.class = 'other'), 0) AS xv,
        sum(v.quantity) AS cq, sum(v.value) AS cv,
        bool_or(NOT v.before) AS moved
      FROM moves v GROUP BY v.item_id
    )
    SELECT i.code, i.name, i.hs_code, coalesce(i.fbr_uom_code, u.name),
      (SELECT r.rate FROM public.tax_rates r
         WHERE r.tenant_id = i.tenant_id AND r.effective_from <= p_to
           AND r.category_id = coalesce(i.tax_category_id, (
             SELECT c.id FROM public.tax_categories c
             WHERE c.tenant_id = i.tenant_id AND c.kind = 'standard' ORDER BY c.created_at, c.name LIMIT 1))
         ORDER BY r.effective_from DESC LIMIT 1),
      z.oq, z.ov, z.iq, z.iv, z.pq, z.pv, -z.sq, -z.sv, z.xq, z.xv, z.cq, z.cv
    FROM sums z
    JOIN public.items i ON i.tenant_id = v_tenant AND i.id = z.item_id
    LEFT JOIN public.units u ON u.tenant_id = i.tenant_id AND u.id = i.base_unit_id
    WHERE z.moved OR z.oq <> 0 OR z.ov <> 0
    ORDER BY i.hs_code NULLS LAST, i.code;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.annex_h1_rows(date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.annex_h1_rows(date, date) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: what the ledger says ──────────────────────────────────────────────────────────
-- What the period's journals put on the four sales tax accounts, by the kind of document that
-- wrote them, so that each annex can be set beside the books: Annex-C beside output and further
-- tax, Annex-A and Annex-B beside input tax, and what was withheld from suppliers.
CREATE FUNCTION app.tax_return_ledger(p_from date, p_to date)
  RETURNS TABLE (control text, source_type text, debit numeric, credit numeric)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tax_return_tenant();
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RAISE EXCEPTION 'a period is needed' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  RETURN QUERY
    SELECT a.control_type, j.source_type, sum(l.debit), sum(l.credit)
    FROM public.journal_lines l
    JOIN public.journals j ON j.tenant_id = l.tenant_id AND j.id = l.journal_id
    JOIN public.accounts a ON a.tenant_id = l.tenant_id AND a.id = l.account_id
    WHERE l.tenant_id = v_tenant AND a.control_type IN ('output_tax', 'further_tax', 'input_tax', 'wht_sales_tax')
      AND j.journal_date BETWEEN p_from AND p_to
    GROUP BY a.control_type, j.source_type
    ORDER BY a.control_type, j.source_type;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.tax_return_ledger(date, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.tax_return_ledger(date, date) TO app_runtime;
